/** Runs against the installed signed launcher without changing user settings. */
public class PageEntryInstrumentation extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 private WebView web(Activity owner,String field)throws Exception {Field f=owner.getClass().getDeclaredField(field);f.setAccessible(true);return (WebView)f.get(owner);}
 private String eval(WebView browser,String expression)throws Exception {CountDownLatch done=new CountDownLatch(1);String[] answer={null};runOnMainSync(()->browser.evaluateJavascript(expression,v->{answer[0]=v;done.countDown();}));if(!done.await(5,TimeUnit.SECONDS))throw new AssertionError("Javascript timed out");return answer[0];}
 private void check(WebView browser,String expression)throws Exception {for(int i=0;i<60;i++){if("true".equals(eval(browser,expression)))return;Thread.sleep(100);}throw new AssertionError(expression+" returned "+eval(browser,expression));}
 private Activity open(String name){return startActivitySync(new Intent().setClassName("local.tvmorph.tv","local.tvmorph.tv."+name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 private void waitClosed(Activity owner)throws Exception {for(int i=0;i<40&&!owner.isFinishing();i++)Thread.sleep(50);if(!owner.isFinishing())throw new AssertionError("Back did not close "+owner.getClass().getSimpleName());}
 private Activity launchBridge(Activity home,WebView hw)throws Exception {ActivityMonitor monitor=addMonitor("local.tvmorph.tv.BridgeReceiverActivity",null,false);eval(hw,"ClearTV.Catalog.launch(ClearTV.Catalog.get('local.tvmorph.tv.bridge'));true");Activity bridge=waitForMonitorWithTimeout(monitor,5000);removeMonitor(monitor);if(bridge==null)throw new AssertionError("Bridge did not open");check(web(bridge,"browser"),"!!window.MorphReceiverBack&&!!document.getElementById('bridge-back')");return bridge;}
 private void phoneBack(Activity home)throws Exception {Field token=home.getClass().getDeclaredField("token");token.setAccessible(true);java.util.Map<String,String> headers=new java.util.HashMap<>();headers.put("x-tv-morph-token",String.valueOf(token.get(home)));java.lang.reflect.Method handle=home.getClass().getDeclaredMethod("handle",String.class,String.class,java.util.Map.class,byte[].class);handle.setAccessible(true);Object response=handle.invoke(home,"POST","/remote/key",headers,"{\"key\":\"RETURN\"}".getBytes("UTF-8"));Field code=response.getClass().getDeclaredField("code");code.setAccessible(true);if(code.getInt(response)!=200)throw new AssertionError("Remote route failed");}
 @Override public void onStart(){Bundle result=new Bundle();try{
 Activity home=open("TvActivity");WebView hw=web(home,"web");check(hw,"!!window.ReferencePreview");org.json.JSONArray report=new org.json.JSONArray();
 eval(hw,"document.getElementById('reference-card-themes').focus();document.getElementById('reference-card-themes').click();true");check(hw,"!document.getElementById('view-settings').hidden");eval(hw,"ClearTV.Remote.key('RETURN');true");Thread.sleep(250);result.putString("themesReturnState",eval(hw,"JSON.stringify({homeHidden:document.getElementById('view-home').hidden,settingsHidden:document.getElementById('view-settings').hidden,active:document.activeElement.id,overlayHidden:document.getElementById('overlay').hidden,dialogs:Array.from(document.querySelectorAll('[role=dialog]')).filter(n=>n.offsetWidth).map(n=>n.id)})"));check(hw,"!document.getElementById('view-home').hidden&&document.activeElement.id==='reference-card-themes'");eval(hw,"ClearTV.Remote.key('LEFT');true");check(hw,"document.activeElement.id==='reference-card-radio'");
 String[][] pages={{"BridgeReceiverActivity","browser","reference-card-bridge"},{"RadioActivity","web","reference-card-radio"},{"NetworkActivity","web","home-local-network"},{"IptvActivity","web","reference-card-iptv"}};
 for(String[] page:pages){ActivityMonitor monitor=addMonitor("local.tvmorph.tv."+page[0],null,false);long start=SystemClock.uptimeMillis();eval(hw,"document.getElementById('"+page[2]+"').focus();document.getElementById('"+page[2]+"').click();true");Activity owner=waitForMonitorWithTimeout(monitor,8000);removeMonitor(monitor);if(owner==null)throw new AssertionError("Entry failed: "+page[0]);WebView view=web(owner,page[1]);boolean[] visible={false};boolean[] fractional={false};for(int frame=0;frame<400;frame++){runOnMainSync(()->{visible[0]=view.getVisibility()==android.view.View.VISIBLE;float alpha=view.getAlpha();if(alpha>0&&alpha<1)fractional[0]=true;});if(visible[0])break;Thread.sleep(10);}long visibleMs=SystemClock.uptimeMillis()-start;if(!visible[0]||fractional[0])throw new AssertionError("Animated or hidden native surface: "+page[0]);if((owner.getIntent().getFlags()&Intent.FLAG_ACTIVITY_NO_ANIMATION)==0)throw new AssertionError("Missing no-animation launch flag: "+page[0]);check(view,"location.href.indexOf('index.html')>=0&&document.readyState==='complete'");check(view,"[document.body].concat(Array.from(document.querySelectorAll('#app,main,#dashboard'))).every(function(n){var s=getComputedStyle(n);return s.transitionDuration==='0s'&&s.animationName==='none';})");if(page[0].equals("IptvActivity")){Field f=owner.getClass().getDeclaredField("entryCover");f.setAccessible(true);android.view.View cover=(android.view.View)f.get(owner);for(int wait=0;wait<60&&cover.getVisibility()!=android.view.View.GONE;wait++)Thread.sleep(50);if(cover.getVisibility()!=android.view.View.GONE||cover.getBackground()!=null)throw new AssertionError("IPTV first-frame cover not released");}String css=eval(view,"JSON.stringify({body:{transition:getComputedStyle(document.body).transitionDuration,animation:getComputedStyle(document.body).animationName},roots:Array.from(document.querySelectorAll('#app,main,#dashboard')).map(function(n){var s=getComputedStyle(n);return [n.id||n.tagName,s.transitionDuration,s.animationName]})})");org.json.JSONObject entry=new org.json.JSONObject().put("page",page[0]).put("nativeVisibleMs",visibleMs).put("fractionalAlpha",fractional[0]).put("noAnimationFlag",true).put("css",css);report.put(entry);runOnMainSync(()->owner.finish());waitClosed(owner);Thread.sleep(100);if(page[0].equals("RadioActivity")){check(hw,"document.activeElement.id==='reference-card-radio'");eval(hw,"ClearTV.Remote.key('RIGHT');true");check(hw,"document.activeElement.id==='reference-card-themes'");eval(hw,"ClearTV.Remote.key('LEFT');true");check(hw,"document.activeElement.id==='reference-card-radio'");}}
 for(String name:new String[]{"apps","settings","inputs","home"}){eval(hw,"ClearTV.showView('"+name+"');true");check(hw,"(function(){var n=document.getElementById('view-"+name+"'),s=getComputedStyle(n);return !n.hidden&&s.transitionDuration==='0s'&&s.animationName==='none';})()");}
 result.putString("report",report.toString());result.putString("result","PASS native home-card entries and in-launcher page roots: no fractional alpha, no activity animations, immediate CSS page switches; load time measured separately");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
